#!/usr/bin/env python3
# scan2.py OUT.jsonl
# Like scan.py (same transcripts, same exclusions), but a Bash or Grep call counts as a read of a part of
# .claude/skills/fortress-repo/ only if (a) it names the part (directly, as fortress-repo/references/NAME, or
# by its bare name in a command that names fortress-repo) and (b) its result holds at least one line of the
# part as the part stood in some commit (git log --all), line-number prefixes of grep -n, cat -n and Read
# stripped, lines of 12 characters or more. Coverage = the part's distinct lines found in the result over the
# lines of the version current at the call's time (main's latest commit of the part before it); whole if
# coverage >= 0.9. Read calls: whole without offset/limit, part with them; a "File unchanged" stub and an
# error are marked. Edit/Write calls are recorded as edits, not reads.
import bisect, glob, json, os, re, subprocess, sys
from multiprocessing import Pool
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import scan as S

REPO = '/home/user/fortress'
PARTS = S.NAMES + ['SKILL.md']

def path_of(n):
    return '.claude/skills/fortress-repo/' + ('SKILL.md' if n == 'SKILL.md' else 'references/' + n)

def norm(l):
    return re.sub(r'\s+', ' ', l).strip()

LINES = {}      # part -> set of normalised lines ever in it
VERS = {}       # part -> sorted [(epoch, n_eligible_lines, n_chars)]
for n in PARTS:
    p = path_of(n)
    out = subprocess.run(['git', '-C', REPO, 'log', '--all', '--format=%H %ct', '--', p], capture_output=True, text=True).stdout.split('\n')
    s = set(); v = []
    for row in out:
        if not row.strip():
            continue
        h, ct = row.split()
        txt = subprocess.run(['git', '-C', REPO, 'show', h + ':' + p], capture_output=True, text=True).stdout
        el = set(norm(x) for x in txt.split('\n') if len(norm(x)) >= 12)
        s |= el
        v.append((int(ct), len(el), len(txt)))
    LINES[n] = s
    VERS[n] = sorted(v)

PREFIX = re.compile(r'^(?:[^\s:]*:)?\s*\d+(?:[\t:→-]|\s{2,})')

def version_at(n, ts):
    import datetime
    if not ts or not VERS.get(n):
        return None
    t = datetime.datetime.fromisoformat(ts.replace('Z', '+00:00')).timestamp()
    v = VERS[n]
    i = bisect.bisect_right([x[0] for x in v], t) - 1
    return v[max(i, 0)]

def match(n, text):
    found = set()
    for l in text.split('\n'):
        l2 = norm(PREFIX.sub('', l, count=1))
        if len(l2) >= 12 and l2 in LINES[n]:
            found.add(l2)
        else:
            l3 = norm(l)
            if len(l3) >= 12 and l3 in LINES[n]:
                found.add(l3)
    return found

def mentions(cmd):
    out = {}
    for m in S.DIRECT.finditer(cmd):
        out[m.group(1) or m.group(2)] = 'direct'
    if 'fortress-repo' in cmd:
        for m in S.BARE.finditer(cmd):
            pre = cmd[max(0, m.start() - 40):m.start()]
            if re.search(r'(coordinator|cloud-container)/(references/)?$', pre):
                continue
            out.setdefault(m.group(1), 'bare')
    return out

def verb_of(cmd, name):
    i = cmd.find(name)
    seg = cmd[:i]
    seg = re.split(r'\|\||&&|;|\n|\||\$\(', seg)[-1]
    w = [x for x in seg.split() if not re.match(r'^\w+=', x)]
    v = os.path.basename(w[0]) if w else ''
    pipe = re.match(r'[^\n|;&]*\|\s*(\w+)', cmd[i:])
    return v, (pipe.group(1) if pipe else '')

def scan(item):
    r, paths = item
    kind = S.kind_of(r)
    uses = {}
    res = {}
    out = []
    for p in paths:
        for line in open(p, errors='replace'):
            if '"tool_use"' not in line and '"tool_result"' not in line:
                continue
            try:
                d = json.loads(line)
            except Exception:
                continue
            c = (d.get('message') or {}).get('content')
            if not isinstance(c, list):
                continue
            for b in c:
                if not isinstance(b, dict):
                    continue
                if b.get('type') == 'tool_use' and b.get('name') in ('Read', 'Bash', 'Grep', 'Edit', 'Write', 'MultiEdit'):
                    uses[b.get('id')] = (d.get('timestamp'), b.get('name'), b.get('input') or {})
                elif b.get('type') == 'tool_result':
                    res[b.get('tool_use_id')] = (S.text_of(b.get('content')), bool(b.get('is_error')))
    for tid, (ts, nm, inp) in uses.items():
        rt, err = res.get(tid, ('', False))
        if nm in ('Read', 'Edit', 'Write', 'MultiEdit'):
            m = S.DIRECT.search(inp.get('file_path') or '')
            if not m:
                continue
            n = m.group(1) or m.group(2)
            if nm != 'Read':
                out.append(dict(ev='edit', rel=r, kind=kind, ts=ts, tool=nm, part=n))
                continue
            mode = 'part' if (inp.get('offset') or inp.get('limit')) else 'whole'
            stub = 'unchanged since last read' in rt.lower() or 'file unchanged' in rt.lower()
            v = version_at(n, ts)
            f = match(n, rt)
            out.append(dict(ev='read', rel=r, kind=kind, ts=ts, tool='Read', part=n, mode=mode, how='direct',
                            offset=inp.get('offset'), limit=inp.get('limit'), err=err, stub=stub,
                            nfound=len(f), nver=v[1] if v else None, cov=round(len(f) / v[1], 3) if v and v[1] else None,
                            res_chars=len(rt), verb='Read'))
        elif nm in ('Bash', 'Grep'):
            if nm == 'Bash':
                cmd = inp.get('command') or ''
                ms = mentions(cmd)
            else:
                pth = inp.get('path') or ''
                ms = {}
                m = S.DIRECT.search(pth)
                if m:
                    ms[m.group(1) or m.group(2)] = 'direct'
                elif 'fortress-repo' in pth or (pth.rstrip('/').endswith('/skills') or pth.rstrip('/').endswith('.claude')):
                    for n in PARTS:
                        if n in rt:
                            ms[n] = 'folder'
                cmd = 'Grep ' + json.dumps(inp)[:300]
            for n, how in ms.items():
                f = match(n, rt)
                v = version_at(n, ts)
                if nm == 'Bash':
                    vb, pipe = verb_of(cmd, n)
                else:
                    vb, pipe = 'Grep', ''
                out.append(dict(ev='read' if f else 'mention', rel=r, kind=kind, ts=ts, tool=nm, part=n, how=how,
                                nfound=len(f), nver=v[1] if v else None, cov=round(len(f) / v[1], 3) if v and v[1] else None,
                                res_chars=len(rt), err=err, verb=vb, pipe=pipe, cmd=cmd[:240]))
    return out

if __name__ == '__main__':
    items = S.files()
    items.sort(key=lambda x: -sum(os.path.getsize(p) for p in x[1]))
    with Pool(4) as pool, open(sys.argv[1], 'w') as f:
        for recs in pool.imap_unordered(scan, items, chunksize=1):
            for x in recs:
                f.write(json.dumps(x) + '\n')
    print('files', len(items))

