                v = version_at(n, ts)
                if nm == 'Bash':
                    vb, pipe = verb_of(cmd, n)
                else:
                    vb, pipe = 'Grep', ''
                out.append(dict(ev='read' if f else 'mention', rel=r, kind=kind, ts=ts, tool=nm, part=n, how=how,
