#!/usr/bin/env python3
# committers.py: which transcript made each commit that touched revival-changes.md. Reads every transcript
# (scan.py's set) for Bash calls whose command holds "git commit" and whose result prints "[branch HASH]";
# matches HASH against the 40 commits of git log --follow on the part; prints commit, date, the transcript's
# group and label.
import json, os, re, subprocess, sys
from multiprocessing import Pool
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import scan as S
F = '.claude/skills/fortress-repo/references/revival-changes.md'
H = subprocess.run(['git', '-C', '/home/user/fortress', 'log', '--follow', '--format=%H %ad %s', '--date=short', '--', F],
                   capture_output=True, text=True).stdout.strip().split('\n')
HASHES = [(h.split()[0], h) for h in H]
PAT = re.compile(r'\[[^\]\s]+(?: \([^)]*\))? ([0-9a-f]{7,40})\]')

def scan(item):
    r, paths = item
    uses, found = {}, []
    for p in paths:
        for line in open(p, errors='replace'):
            if 'git commit' not in line and 'tool_result' not in line:
                continue
            try:
                d = json.loads(line)
            except Exception:
                continue
            c = (d.get('message') or {}).get('content')
            if not isinstance(c, list):
                continue
            for b in c:
                if not isinstance(b, dict):
                    continue
                if b.get('type') == 'tool_use' and b.get('name') == 'Bash' and 'git commit' in ((b.get('input') or {}).get('command') or ''):
                    uses[b['id']] = d.get('timestamp')
                elif b.get('type') == 'tool_result' and b.get('tool_use_id') in uses:
                    for m in PAT.finditer(S.text_of(b.get('content'))):
                        for full, row in HASHES:
                            if full.startswith(m.group(1)):
                                found.append((row, r, uses[b['tool_use_id']]))
    return found

if __name__ == '__main__':
    AG = {}
    for l in open(os.path.dirname(os.path.abspath(__file__)) + '/scan.jsonl'):
        a = json.loads(l)
        if a['ev'] == 'agent':
            AG[a['rel']] = a
    items = S.files()
    with Pool(4) as pool:
        res = [x for L in pool.imap_unordered(scan, items, chunksize=1) for x in L]
    by = {}
    for row, r, ts in res:
        by.setdefault(row, set()).add(r)
    for full, row in HASHES[::-1]:
        who = by.get(row, set())
        desc = '; '.join('%s %s' % (AG.get(r, {}).get('kind', '?'), (AG.get(r, {}).get('desc') or (AG.get(r, {}).get('prompt_head') or '')[:60]).replace('\n', ' ')[:60]) for r in who) or '(no transcript found)'
        print(row[:9], row.split()[1], '|', desc)

